using System;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Web.Script.Serialization;using ReplierDesktop;
public static class CandidateIsolationChecks {
 static void Check(bool b,string s){if(!b)throw new Exception(s);Console.WriteLine("PASS "+s);}
 public static int Main(){try{var json=new JavaScriptSerializer();var v=new Video{Id="V0000000001",Title="제한시간 컨트롤"};var c=new VideoContent{Version=1,VideoId=v.Id,Language="ko",Source="YouTube 공개 자막",AcquiredAt=DateTime.UtcNow.ToString("o"),Cues=new List<CaptionCue>{new CaptionCue{Text="시간 안에 동시에 조작합니다.",DurationMs=1000}}};var rows=new[]{new CommentSuggestion{Text="이 조작은 신기하네요",Material="{\"context_version\":2}"},new CommentSuggestion{Text="시간 안에 동시에 조작하는 게 신기하네요",Material="{\"context_version\":2}"}};var calls=new Dictionary<string,int>();
 using(var g=new LocalModel("unused",DualCommentService.Models[0]))using(var q=new LocalModel("unused",DualCommentService.Models[1])){
 Func<string,Func<object,CancellationToken,Task<string>>> sender=name=>(body,token)=>{token.ThrowIfCancellationRequested();var req=SceneMaterial.Json(json.Serialize(body));var props=CaptionService.Get(CaptionService.Get(req,"format"),"properties");var msgs=(object[])CaptionService.Get(req,"messages");string last=(string)CaptionService.Get(msgs.Last(),"content");
 if(CaptionService.Get(props,"references")!=null){var input=SceneMaterial.Json(last);string text=(string)CaptionService.Get(input,"comment");if(name==g.Name&&text==rows[0].Text){if(!calls.ContainsKey(name))calls[name]=0;calls[name]++;return Task.FromResult("{\"references\":[{\"name\":\"댓글에없는이름\",\"identity\":\"work\"}]}");}return Task.FromResult("{\"references\":[]}");}
 if(CaptionService.Get(props,"voices")!=null)return Task.FromResult("{\"voices\":[{\"id\":0,\"voice\":\"viewer\"}]}");
 if(CaptionService.Get(props,"source")!=null){var input=SceneMaterial.Json(last);return Task.FromResult(json.Serialize(new{evaluated_comment=(string)CaptionService.Get(input,"candidate_comment"),premise="동시에 조작한다",supported=true,context_clear=true,added_claim=false,asserts_event_result=false,source_kind="no_event",comment_outcome="none",context_outcome="undetermined",source=0,rationale="실제 조작 설명에 대한 감상"}));}
 string target=last.Substring("평가할 댓글: ".Length);return Task.FromResult(json.Serialize(new{evaluated_comment=target,focus="시간 제한 조작",evidence=0,source_role="central_event",conflicts=false,explanation="동시 조작에 대한 감상"}));};
 var score=new CombinedFitScoring(new FitScoring(g,sender(g.Name)),new FitScoring(q,sender(q.Name)),()=>Task.FromResult(0));score.Evaluate(v,c,rows,CancellationToken.None).GetAwaiter().GetResult();
 Check(rows[0].FitEligible==false&&!rows[0].FitScore.HasValue,"malformed name response leaves only that candidate unverified rather than assigning a false score");Check(rows[0].FitError.Contains(g.Name)&&rows[0].FitError.Contains("댓글에없는이름"),"failed model and extracted name are visible in candidate debug reason");Check(rows[1].FitEligible==true&&rows[1].FitScore==90,"remaining candidate is scored by both models and remains displayable");Check(calls[g.Name]==2,"name correction retry remains bounded to one retry");
 var canceledToken=new CancellationToken(true);bool canceled=false;try{score.Evaluate(v,c,rows,canceledToken).GetAwaiter().GetResult();}catch(OperationCanceledException){canceled=true;}Check(canceled,"candidate isolation never swallows user cancellation");
 var result=new DualCommentResult{Complete=true,Batches=new List<ModelCommentBatch>{new ModelCommentBatch{Label="Gemma",Result=new CommentResult{Comments=rows.ToList()}}}};string debug=CommentDebugReport.Format(v,result,rows[1],"검사","");Check(debug.Contains("후보별 평가 오류")&&debug.Contains("댓글에없는이름"),"copy debug includes the failed candidate without hiding the healthy winner");
 }return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
